// This simulates what you'd run in mongosh
// In a real terminal, these would run against an actual MongoDB server

// Simulated database state
const db = {
  users: [],
  products: []
};

// Simulate insertOne
function insertOne(collection, doc) {
  const newDoc = { _id: Math.random().toString(36).slice(2), ...doc };
  db[collection].push(newDoc);
  return { acknowledged: true, insertedId: newDoc._id };
}

// Simulate findOne
function findOne(collection, filter = {}) {
  return db[collection].find(doc =>
    Object.entries(filter).every(([k, v]) => doc[k] === v)
  ) || null;
}

// Try it out
console.log(insertOne('users', { name: 'Alice', email: 'alice@example.com' }));
console.log(insertOne('users', { name: 'Bob', email: 'bob@example.com' }));
console.log('Find Alice:', findOne('users', { name: 'Alice' }));
console.log('All users:', db.users);
